// 4 days/week, ~75 min sessions, hard intensity. Equipment: Resistance bands, Barbell, rack & bench, Dual adjustable pulley (cable), Dumbbells & bench, Kettlebells, Lat pulldown station, Pull-up bar.
# Week 1
// Estimated ~75 min
## Upper A
// Shoulder blades pinched, bar to lower chest, feet planted.
Bench Press, Barbell / 3x5, 1x5+ / 20kg / 180s / progress: lp(2.5kg, 1, 0, 10%, 2, 0)
// Hand on the bench, pull the dumbbell to your hip.
Bent Over One Arm Row, Dumbbell / 3x5, 1x5+ / 12kg / 180s / progress: dp(2kg, 5, 9)
// Seated or standing, press up without arching your back.
Shoulder Press, Dumbbell / 3x5, 1x5+ / 8kg / 180s / progress: dp(2kg, 5, 9)
// Thighs under the pad, pull the bar to your upper chest.
Lat Pulldown, Cable / 3x5, 1x5+ / 25kg / 180s / progress: dp(2.5kg, 5, 9)
// Elbows pinned to your sides, no swinging.
Bicep Curl, Dumbbell / 3x8 / 6kg / 90s / warmup: none / progress: dp(2kg, 8, 12)
// Pulley high, elbows pinned, push down to lockout.
Triceps Pushdown, Cable / 3x8 / 12.5kg / 90s / warmup: none / progress: dp(2.5kg, 8, 12)

// Estimated ~51 min
## Lower A
// Brace, sit between your hips, knees track over toes.
Squat, Barbell / 3x5, 1x5+ / 20kg / 180s / progress: lp(2.5kg, 1, 0, 10%, 2, 0)
// Low pulley with rope, face away, hinge and squeeze glutes.
Cable Pull Through, Cable / 3x5, 1x5+ / 15kg / 180s / progress: dp(2.5kg, 5, 9)
// Feet staggered, drop the back knee straight down.
Split Squat, Dumbbell / 3x8 / 6kg / 90s / warmup: none / progress: dp(2kg, 8, 12)
// On a step if you can, pause at the top.
Standing Calf Raise, Dumbbell / 3x8 / 10kg / 90s / warmup: none / progress: dp(2kg, 8, 12)
// Low back pressed into the floor, extend opposite arm and leg.
Dead Bug, Bodyweight / 3x8, 1x8+ / 0kg / 90s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}

// Estimated ~69 min
## Upper B
// Squeeze glutes, press the bar up and move your head through.
Overhead Press, Barbell / 3x5, 1x5+ / 20kg / 180s / progress: lp(2.5kg, 1, 0, 10%, 2, 0)
// Palms facing you, pull chin over the bar. Do negatives if needed.
Chin Up, Bodyweight / 3x8, 1x8+ / 0kg / 90s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Bench at ~30°, press up and slightly back.
Incline Bench Press, Dumbbell / 3x5, 1x5+ / 8kg / 180s / progress: dp(2kg, 5, 9)
// Chest on an incline bench, row elbows back.
Chest-Supported Row, Dumbbell / 3x5, 1x5+ / 10kg / 180s / progress: dp(2kg, 5, 9)
// Anchor at face height, pull toward your forehead, thumbs back.
Face Pull, Band / 3x8, 1x8+ / 0kg / 90s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Palms facing each other the whole time.
Hammer Curl, Dumbbell / 3x8 / 6kg / 90s / warmup: none / progress: dp(2kg, 8, 12)

// Estimated ~51 min
## Lower B
// Bar over mid-foot, flat back, push the floor away.
Deadlift, Barbell / 3x5, 1x5+ / 40kg / 180s / progress: lp(5kg, 1, 0, 10%, 2, 0)
// Hold the dumbbell at your chest, elbows inside knees.
Goblet Squat, Dumbbell / 3x5, 1x5+ / 12kg / 180s / progress: dp(2kg, 5, 9)
// Upper back on the bench, chin tucked, squeeze at the top.
Hip Thrust, Barbell / 3x8 / 30kg / 90s / warmup: none / progress: dp(2.5kg, 8, 12)
// Step back, front shin vertical, push through the front heel.
Reverse Lunge, Dumbbell / 3x8 / 6kg / 90s / warmup: none / progress: dp(2kg, 8, 12)
// Hang still, bring knees up without swinging.
Hanging Knee Raise, Bodyweight / 3x8, 1x8+ / 0kg / 90s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
